const DEVELOPMENT_GATE = false;
if (!DEVELOPMENT_GATE) throw new Error('DEVELOPMENT_GATE_CLOSED: approve a read-only health check before changing this value');
return $input.all();

const rows = $input.all().map(i => i.json);
const byKey = new Map(rows.filter(r => r?.source_key).map(r => [r.source_key, r]));
const now = Date.now();
const hour = 60 * 60 * 1000;
const required = [
  { key: 'shopify_orders', maxAgeMs: 2 * hour },
  { key: 'shopify_sales_events', maxAgeMs: 2 * hour },
  { key: 'shopify_products', maxAgeMs: 8 * hour },
  { key: 'shopify_customer_company_directory', maxAgeMs: 8 * hour },
  { key: 'amazon_us_orders', maxAgeMs: 8 * hour },
  { key: 'amazon_uk_orders', maxAgeMs: 8 * hour },
  { key: 'ga4_traffic', maxAgeMs: 12 * hour },
];
const stale = required.filter(({ key, maxAgeMs }) => {
  const when = Date.parse(byKey.get(key)?.last_success_at || '');
  return !Number.isFinite(when) || now - when > maxAgeMs;
}).map(({ key }) => key);
if (stale.length) throw new Error(`SYNC_HEALTH_STALE:${stale.join(',')}`);
return [{ json: {
  status: 'healthy',
  checkedAt: new Date().toISOString(),
  sources: required.map(({ key }) => ({
    source_key: key,
    last_success_at: byKey.get(key)?.last_success_at || null,
  })),
} }];
